"""Typed predicate expressions.

Predicates arrive as JSON expression arrays.  They are compiled once per
module into small closures so that every recorded witness can be checked
without re-walking the source form.  Scoping is lexical: an ``all`` binding
shadows an outer binding of the same name without touching it.
"""

from .ast import (Alias, Bool, Int, String, constant_value, values_equal)
from . import regex as pattern_language

COMPARISONS = ('eq', 'ne', 'lt', 'le', 'gt', 'ge')
ARITHMETIC = ('add', 'sub')
LOGICAL = ('and', 'or', 'implies')
BINARY = COMPARISONS + ARITHMETIC + LOGICAL


class ExpressionError(ValueError):
    """Raised when a predicate does not fit the documented grammar."""


def _truth(value):
    return bool(value)


def compile_expression(node, scope, types):
    """Compile one expression node into a `(type, function)` pair."""
    if not isinstance(node, list) or not node:
        raise ExpressionError('malformed expression')
    tag = node[0]
    if tag == 'var':
        name = node[1]
        if name not in scope:
            raise ExpressionError('unknown variable: ' + str(name))
        type = scope[name]
        return type, _var(name)
    if tag == 'const':
        type = types.get(node[1])
        value = constant_value(type, node[2])
        return type, _const(value)
    if tag == 'field':
        base_type, base = compile_expression(node[1], scope, types)
        base_type = base_type.inner()
        if base_type.kind != 'struct':
            raise ExpressionError('field of a non-struct value')
        field = node[2]
        field_type = base_type.field(field)
        return field_type, _field(base, field)
    if tag == 'index':
        base_type, base = compile_expression(node[1], scope, types)
        base_type = base_type.inner()
        if base_type.kind != 'array':
            raise ExpressionError('index of a non-array value')
        position = node[2]
        if not isinstance(position, int) or isinstance(position, bool):
            raise ExpressionError('index must be an integer')
        if position < 0 or position >= base_type.size:
            raise ExpressionError('index out of range')
        return base_type.element, _index(base, position)
    if tag == 'all':
        binding = node[1]
        base_type, base = compile_expression(node[2], scope, types)
        base_type = base_type.inner()
        if base_type.kind != 'array':
            raise ExpressionError('all over a non-array value')
        inner_scope = dict(scope)
        inner_scope[binding] = base_type.element
        _, body = compile_expression(node[3], inner_scope, types)
        return Bool(), _all(base, body, binding)
    if tag == 'match':
        base_type, base = compile_expression(node[1], scope, types)
        base_type = base_type.inner()
        if base_type.kind != 'string':
            raise ExpressionError('match of a non-string value')
        program = pattern_language.compile_pattern(node[2])
        return Bool(), _match(base, program)
    if tag == 'not':
        _, body = compile_expression(node[1], scope, types)
        return Bool(), _not(body)
    if tag in BINARY:
        left_type, left = compile_expression(node[1], scope, types)
        right_type, right = compile_expression(node[2], scope, types)
        return _binary(tag, left_type, left, right_type, right)
    raise ExpressionError('unknown expression form: ' + str(tag))


def _var(name):
    def evaluate(context):
        return context[name]
    return evaluate


def _const(value):
    def evaluate(context):
        return value
    return evaluate


def _field(base, field):
    def evaluate(context):
        return base(context)[field]
    return evaluate


def _index(base, position):
    def evaluate(context):
        return base(context)[position]
    return evaluate


def _all(base, body, binding):
    def evaluate(context):
        items = base(context)
        if not items:
            return True
        inner = dict(context)
        for item in items:
            inner[binding] = item
            if not _truth(body(inner)):
                return False
        return True
    return evaluate


def _match(base, program):
    def evaluate(context):
        return pattern_language.fullmatch(program, base(context))
    return evaluate


def _not(body):
    def evaluate(context):
        return not _truth(body(context))
    return evaluate


def _binary(op, left_type, left, right_type, right):
    if op in COMPARISONS:
        compare_type = left_type.inner()
        if op == 'eq':
            def evaluate(context):
                return values_equal(compare_type, left(context), right(context))
        elif op == 'ne':
            def evaluate(context):
                return not values_equal(compare_type, left(context), right(context))
        else:
            def evaluate(context):
                one = left(context)
                two = right(context)
                if op == 'lt':
                    return one < two
                if op == 'le':
                    return one <= two
                if op == 'gt':
                    return one > two
                return one >= two
        return Bool(), evaluate
    if op in ARITHMETIC:
        number_type = left_type.inner()
        if number_type.kind != 'int':
            raise ExpressionError('arithmetic on a non-integer value')
        modulus = number_type.modulus()
        if op == 'add':
            def evaluate(context):
                return (left(context) + right(context)) % modulus
        else:
            def evaluate(context):
                return (left(context) - right(context)) % modulus
        return number_type, evaluate
    if op == 'and':
        def evaluate(context):
            return _truth(left(context)) and _truth(right(context))
    elif op == 'or':
        def evaluate(context):
            return _truth(left(context)) or _truth(right(context))
    else:
        def evaluate(context):
            return (not _truth(left(context))) or _truth(right(context))
    return Bool(), evaluate


def compile_predicate(node, scope, types):
    """Compile a predicate into a function of the visible variables."""
    if node is None:
        return None
    _, evaluate = compile_expression(node, scope, types)
    return evaluate
"""Symbolic layout compilation for entry harnesses.

The numbering contract follows the toolkit's ``MainBuilder`` convention:
inputs in parameter order, then a non-void result, starting at ``x0``.  Every
visited bool, char, int, enum, string buffer, array or struct reserves one
increasing identifier.  A composite reserves an identifier for itself but
contributes no symbolic object of its own; its children follow in order.
String buffers reserve their identifier and are followed by one character
object per declared byte.  Aliases are transparent and reserve nothing.
"""

from .ast import Alias

SCALAR_WIDTHS = {'bool': 1, 'char': 1, 'enum': 4}


class LayoutError(ValueError):
    """Raised when a type cannot be laid out."""


class Layout(object):
    """The compiled harness layout of one entry module."""

    __slots__ = ('slots', 'count', 'roots', 'result')

    def __init__(self):
        self.slots = []
        self.count = 0
        self.roots = []
        self.result = None


class LayoutBuilder(object):
    """Reserves symbolic identifiers for a typed harness."""

    def __init__(self):
        self.slots = []
        self.count = 0

    def _reserve(self):
        identifier = self.count
        self.count += 1
        return identifier

    def build(self, type, path):
        """Return the layout node of `type` reached through `path`."""
        while isinstance(type, Alias):
            type = type.target
        identifier = self._reserve()
        kind = type.kind
        if kind == 'bool':
            self.slots.append(('x%d' % identifier, list(path), 1))
            return ('bool', identifier)
        if kind == 'char':
            self.slots.append(('x%d' % identifier, list(path), 1))
            return ('char', identifier)
        if kind == 'int':
            self.slots.append(('x%d' % identifier, list(path), type.width()))
            return ('int', identifier, type.bits)
        if kind == 'enum':
            self.slots.append(('x%d' % identifier, list(path), 4))
            return ('enum', identifier, list(type.values))
        if kind == 'string':
            for position in range(type.maxsize):
                character = self._reserve()
                self.slots.append(('x%d' % character, list(path) + [position], 1))
            return ('string', identifier, type.maxsize)
        if kind == 'array':
            children = [self.build(type.element, list(path) + [position])
                        for position in range(type.size)]
            return ('array', identifier, children)
        if kind == 'struct':
            children = [(name, self.build(field_type, list(path) + [name]))
                        for name, field_type in type.fields]
            return ('struct', identifier, children)
        raise LayoutError('cannot lay out a ' + kind + ' value')


class DeclarationCollector(object):
    """Collects the enum, struct and alias declarations a plan needs.

    Declarations are emitted dependency before user: a post-order walk that
    visits struct fields in order and array and alias children first.
    """

    def __init__(self):
        self.declarations = []
        self.seen = set()

    def collect(self, type):
        """Record every declaration reachable from `type`."""
        if isinstance(type, Alias):
            if type.name in self.seen:
                return
            self.seen.add(type.name)
            self.collect(type.target)
            self.declarations.append(type.name)
            return
        kind = type.kind
        if kind == 'struct':
            if type.name in self.seen:
                return
            self.seen.add(type.name)
            for _name, field_type in type.fields:
                self.collect(field_type)
            self.declarations.append(type.name)
            return
        if kind == 'enum':
            if type.name in self.seen:
                return
            self.seen.add(type.name)
            self.declarations.append(type.name)
            return
        if kind == 'array':
            self.collect(type.element)
            return

    def result(self):
        return list(self.declarations)


def recover(node, values):
    """Rebuild the value of a layout node from recovered object values."""
    kind = node[0]
    if kind == 'bool':
        value = values[node[1]]
        if value != 0 and value != 1:
            raise LeafError('boolean out of range')
        return value == 1
    if kind == 'char':
        return chr(values[node[1]])
    if kind == 'int':
        value = values[node[1]]
        if value >> node[2]:
            raise LeafError('integer padding bits set')
        return value
    if kind == 'enum':
        value = values[node[1]]
        if value >= len(node[2]):
            raise LeafError('enum index out of range')
        return node[2][value]
    if kind == 'string':
        identifier, length = node[1], node[2]
        characters = []
        for position in range(length):
            characters.append(chr(values[identifier + 1 + position]))
        text = ''.join(characters)
        cut = text.find('\x00')
        if cut >= 0:
            return text[:cut]
        return text
    if kind == 'array':
        return [recover(child, values) for child in node[2]]
    if kind == 'struct':
        result = {}
        for name, child in node[2]:
            result[name] = recover(child, values)
        return result
    raise LeafError('unknown layout node')


class LeafError(ValueError):
    """Raised when a recovered leaf value is out of its declared range."""
